package main

import (
        "fmt"
        "sync"
        "time"
)

type Job struct {
        ID int
}

type Result struct {
        JobID int
        Val   int
}

// ProcessJobs processes n jobs using m workers.
// Use this function signature for testing.
// It returns the number of processed jobs and an error if something goes wrong.
func ProcessJobs(numJobs, numWorkers int) (int, error) {
        jobs := make(chan Job, 100)
        results := make(chan Result, 100) // Small buffer creates pressure
        var processedCount int            // RACE CONDITION: Not thread-safe

        var wg sync.WaitGroup

        // Start workers
        for i := 0; i < numWorkers; i++ {
                wg.Add(1)
                go func(id int) {
                        defer wg.Done()
                        for job := range jobs {
                                // Simulate some work
                                time.Sleep(time.Millisecond)

                                // BUG 1: Race Condition
                                processedCount++

                                // BUG 2: Potential Deadlock if buffer fills
                                // Workers block here if no one reads 'results'
                                results <- Result{JobID: job.ID, Val: job.ID * 2}
                        }
                }(i)
        }

        // Send jobs
        go func() {
                for i := 0; i < numJobs; i++ {
                        jobs <- Job{ID: i}
                }
                close(jobs)
        }()

        // BUG 2 (Deadlock Cause): We wait for workers to finish BEFORE reading results.
        // If 'results' channel fills up (buffer=100, jobs=1000), workers will block infinitely.
        // 'wg.Wait()' will never return.
        wg.Wait()
        close(results)

        // Consume results (Too late!)
        for range results {
                // Just drain
        }

        return processedCount, nil
}

func main() {
        count, err := ProcessJobs(1000, 10)
        if err != nil {
                fmt.Printf("Error: %v\n", err)
                return
        }
        fmt.Printf("Successfully processed %d jobs\n", count)
}

package main

import (
        "fmt"
        "testing"
        "time"
)

func TestProcessJobs(t *testing.T) {
        numJobs := 1000
        numWorkers := 10

        done := make(chan struct{})
        var count int
        var err error

        go func() {
                count, err = ProcessJobs(numJobs, numWorkers)
                close(done)
        }()

        select {
        case <-done:
                if err != nil {
                        t.Fatalf("ProcessJobs returned error: %v", err)
                }
                // Check for race condition evidence (count mismatch)
                // With 1000 jobs and a race, count is usually < 1000.
                if count != numJobs {
                        t.Errorf("Race Condition detected? Expected %d processed jobs, got %d", numJobs, count)
                }
        case <-time.After(2 * time.Second):
                t.Fatal("Deadlock detected! ProcessJobs timed out after 2s")
        }
        fmt.Printf("Test passed: Processed %d jobs without deadlock.\n", count)
}

